1	import Link from "next/link";
2	import { ArrowRight } from "lucide-react";
3	import { Card } from "@/components/ui/Card";
4	import { Button } from "@/components/ui/Button";
5	import { Availability } from "@/components/ui/Availability";
6	import { requireRole } from "@/lib/auth";
7	import { listProviderBookings } from "@/lib/db/queries";
8	import { t } from "@/lib/i18n";
9	
10	export const metadata = {
11	  title: `${t("provider.sessionsTitle")} · ${t("app.name")}`,
12	};
13	
14	export default async function ProviderSessionsPage() {
15	  const profile = await requireRole("provider");
16	  const bookings = await listProviderBookings(profile.id);
17	  const active = bookings.filter(
18	    (b) => b.status === "confirmed" || b.status === "in_progress",
19	  );
20	
21	  return (
22	    <div className="flex flex-col gap-6">
23	      <div className="flex flex-col gap-1.5">
24	        <h1 className="text-h1">{t("provider.sessionsTitle")}</h1>
25	        <p className="text-lg text-ink-soft">{t("provider.sessionsSubtitle")}</p>
26	      </div>
27	
28	      {active.length === 0 ? (
29	        <Card>
30	          <p className="text-base text-ink-soft">{t("provider.sessionsNone")}</p>
31	        </Card>
32	      ) : (
33	        <ul className="flex flex-col gap-3">
34	          {active.map((b) => (
35	            <Card
36	              as="li"
37	              key={b.id}
38	              className="flex flex-wrap items-center justify-between gap-3"
39	            >
40	              <div className="flex items-center gap-3">
41	                <Availability
42	                  status={b.status === "in_progress" ? "busy" : "available"}
43	                />
44	                <span className="text-base font-bold text-ink">
45	                  {t("provider.sessionReqLabel", { minutes: b.block_minutes })}
46	                </span>
47	              </div>
48	              <Link href={`/provider/session/${b.id}`} className="rounded-btn">
49	                <Button icon={ArrowRight}>{t("provider.openSession")}</Button>
50	              </Link>
51	            </Card>
52	          ))}
53	        </ul>
54	      )}
55	    </div>
56	  );
57	}
