2	import { CircleCheck, Clock, CalendarDays, type LucideIcon } from "lucide-react";
3	import { t } from "@/lib/i18n";
4	
5	export type AvailabilityStatus = "available" | "busy" | "scheduled";
6	
7	const MAP: Record<
8	  AvailabilityStatus,
9	  { icon: LucideIcon; labelKey: "availability.available" | "availability.busy" | "availability.scheduled"; className: string }
10	> = {
11	  available: {
12	    icon: CircleCheck,
13	    labelKey: "availability.available",
14	    className: "bg-success-tint text-success",
15	  },
16	  busy: {
17	    icon: Clock,
18	    labelKey: "availability.busy",
19	    className: "bg-surface-sunk text-ink-soft",
20	  },
21	  scheduled: {
22	    icon: CalendarDays,
23	    labelKey: "availability.scheduled",
24	    className: "bg-accent-tint text-accent-dark",
25	  },
26	};
27	
28	/**
29	 * Availability pill — status conveyed by icon + text label together, never by
30	 * color alone (SPEC §10 / design system).
31	 */
32	export function Availability({ status }: { status: AvailabilityStatus }) {
33	  const { icon: Icon, labelKey, className } = MAP[status];
34	  return (
35	    <span
36	      className={[
37	        "inline-flex items-center gap-1.5 whitespace-nowrap rounded-pill px-2.5 py-1 text-sm font-bold",
38	        className,
39	      ].join(" ")}
40	    >
41	      <Icon size={15} strokeWidth={2.25} aria-hidden="true" />
42	      {t(labelKey)}
43	    </span>
44	  );
45	}
